      de: ["Gegründet im Jahr 1872 als La Palma.", "Umbenannt 1934 nach James Humberstone.", "UNESCO-Weltkulturerbe seit 2005.", "Wurde 1960 offiziell stillgelegt.", "Beherbergt ein gut erhaltenes Theater.", "Befindet sich 48 km östlich von Iquique."],
