      de: ["Gegründet 1905 von William Braden.", "Bekannt als die Stadt der Treppen.", "UNESCO-Weltkulturerbe seit 2006.", "Liegt auf einer Höhe von 2.140 Metern.", "Keine Straßen für Autos im Stadtgebiet.", "Hatte einst über 15.000 Einwohner."],
