      ro: ["Construit în anul 1770 sub domnia regelui spaniol Carol al III-lea.", "Ultima fortăreață spaniolă din Chile care a capitulat în anul 1826.", "Expune mai multe tunuri din bronz turnate în anul 1820.", "A asigurat apărarea orașului Ancud și a canalului Chacao.", "Situl este protejat ca patrimoniu istoric și monument național.", "Situat strategic în extremitatea nordică a insulei Chiloé."],
