      pt: ["Instalação de fortificação histórica em Ancud do final do século XVIII.", "Um dos últimos pontos de defesa da coroa espanhola na América do Sul.", "Localização importante para a segurança militar da ilha de Chiloé.", "Abriga canhões bem preservados e historicamente significativos."],
