      hu: ["Teljesen vasszögek használata nélkül épült.", "Az építését 1730-ban kezdték jezsuita misszionáriusok."],
      ro: ["Construită complet fără a folosi cuie de fier.", "Începută în 1730 de misionarii iezuiți."],
