      hu: ["Az éves fesztivál során több ezer látogatónak ad helyet.", "A hagyományos fafeldolgozás mesterműve."],
      ro: ["Găzduiește mii de vizitatori la festivalul anual.", "O capodoperă a prelucrării tradiționale a lemnului."],
      en: ["Accommodates thousands of visitors during the annual festival.", "A masterpiece of traditional woodworking."],
      es: ["Tiene espacio para miles de visitantes en la fiesta anual.", "Una obra maestra de la carpintería tradicional en madera."],
      pt: ["Tem espaço para milhares de visitantes na festa anual.", "Uma obra-prima da carpintaria tradicional em madeira."],
      fr: ["Peut accueillir des milliers de visiteurs lors de la fête annuelle.", "Un chef-d'œuvre du travail traditionnel du bois."],
